package com.example;

import com.example.updatetimer.UpdateTimerPlugin;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ExamplePluginTest {
	public static void main(String[] args) throws Exception {
		ExternalPluginManager.loadBuiltin(UpdateTimerPlugin.class);
		RuneLite.main(args);
	}
}

package com.example.updatetimer;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Alpha;

@ConfigGroup("customupdatetimer")
public interface UpdateTimerConfig extends Config {

    @ConfigSection(
            name = "Test Settings",
            description = "Settings for testing the overlay without an active game update",
            position = 0
    )
    String testSection = "testSection";

    @ConfigItem(
            keyName = "enableTestMode",
            name = "Enable Test Mode",
            description = "Forces the overlay to display a fake update timer for testing layout and settings.",
            section = testSection,
            position = 1
    )
    default boolean enableTestMode() {
        return false;
    }

    @ConfigItem(
            keyName = "testMinutes",
            name = "Test Timer (Minutes)",
            description = "Sets the duration of the fake timer during test mode.",
            section = testSection,
            position = 2
    )
    default int testMinutes() {
        return 15;
    }

    @ConfigSection(
            name = "Appearance",
            description = "Font, color, and styling settings",
            position = 10
    )
    String appearanceSection = "appearanceSection";

    enum FontType {
        RUNESCAPE("RuneScape Regular"),
        BOLD("RuneScape Bold"),
        SMALL("RuneScape Small");

        private final String name;
        FontType(String name) { this.name = name; }
        @Override public String toString() { return name; }
    }

    @ConfigItem(
            keyName = "fontType",
            name = "Font Type",
            description = "Select the font style for the update overlay.",
            section = appearanceSection,
            position = 11
    )
    default FontType fontType() {
        return FontType.BOLD;
    }

    @Alpha
    @ConfigItem(
            keyName = "textColor",
            name = "Timer Color",
            description = "Color of the update timer text.",
            section = appearanceSection,
            position = 12
    )
    default Color textColor() {
        return new Color(255, 85, 85);
    }

    @Alpha
    @ConfigItem(
            keyName = "backgroundColor",
            name = "Background Color",
            description = "Background color of the overlay box.",
            section = appearanceSection,
            position = 13
    )
    default Color backgroundColor() {
        return new Color(20, 20, 20, 200);
    }

    @ConfigItem(
            keyName = "flashWarning",
            name = "Flash Under 2 Mins",
            description = "Causes the overlay text to highlight when less than 2 minutes remain.",
            section = appearanceSection,
            position = 14
    )
    default boolean flashWarning() {
        return true;
    }
}

package com.example.updatetimer;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class UpdateTimerOverlay extends OverlayPanel {

    private final Client client;
    private final UpdateTimerConfig config;
    private final UpdateTimerPlugin plugin;

    @Inject
    private UpdateTimerOverlay(Client client, UpdateTimerConfig config, UpdateTimerPlugin plugin) {
        this.client = client;
        this.config = config;
        this.plugin = plugin;

        setPosition(OverlayPosition.TOP_CENTER);
        setPriority(OverlayPriority.HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        int updateTicks = plugin.getSystemUpdateTicks();

        if (config.enableTestMode()) {
            if (plugin.getTestTicksRemaining() <= 0) {
                plugin.resetTestTicks(config.testMinutes());
            }
            updateTicks = plugin.getTestTicksRemaining();
        } else if (updateTicks <= 0) {
            return null;
        }

        Font customFont = getSelectedFont(config.fontType());
        graphics.setFont(customFont);

        int totalSeconds = (int) Math.ceil(updateTicks * 0.6);
        int minutes = totalSeconds / 60;
        int seconds = totalSeconds % 60;

        String timeFormatted = String.format("%02d:%02d", minutes, seconds);

        panelComponent.setPreferredSize(new Dimension(150, 0));
        panelComponent.setBackgroundColor(config.backgroundColor());

        String titleText = config.enableTestMode() ? "UPDATE (TEST)" : "GAME UPDATE";
        panelComponent.getChildren().add(TitleComponent.builder()
                .text(titleText)
                .color(Color.WHITE)
                .build());

        Color textColor = config.textColor();
        if (config.flashWarning() && minutes < 2) {
            if ((totalSeconds % 2) == 0) {
                textColor = Color.YELLOW;
            }
        }

        panelComponent.getChildren().add(LineComponent.builder()
                .left("System Update:")
                .right(timeFormatted)
                .rightColor(textColor)
                .build());

        return super.render(graphics);
    }

    private Font getSelectedFont(UpdateTimerConfig.FontType fontType) {
        switch (fontType) {
            case BOLD:
                return FontManager.getRunescapeBoldFont();
            case SMALL:
                return FontManager.getRunescapeSmallFont();
            case RUNESCAPE:
            default:
                return FontManager.getRunescapeFont();
        }
    }
}

package com.example.updatetimer;

import javax.inject.Inject;
import com.google.inject.Provides;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

@PluginDescriptor(
        name = "Custom Update Timer",
        description = "Displays a moveable, stylized countdown for game updates independently of chat settings.",
        tags = {"update", "timer", "overlay", "system"}
)
public class UpdateTimerPlugin extends Plugin {

    private static final Pattern UPDATE_PATTERN = Pattern.compile("System update in: (?:(\\d+) minute)?s?,? ?(?:(\\d+) second)?s?");

    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private UpdateTimerOverlay overlay;

    private int systemUpdateTicks = 0;
    private int testTicksRemaining = 0;

    @Override
    protected void startUp() throws Exception {
        overlayManager.add(overlay);
    }

    @Override
    protected void shutDown() throws Exception {
        overlayManager.remove(overlay);
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        // Reads official game update system broadcasts directly
        if (event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.ENGINE) {
            Matcher matcher = UPDATE_PATTERN.matcher(event.getMessage());
            if (matcher.find()) {
                int minutes = matcher.group(1) != null ? Integer.parseInt(matcher.group(1)) : 0;
                int seconds = matcher.group(2) != null ? Integer.parseInt(matcher.group(2)) : 0;

                // Convert total seconds to game ticks (1 tick = 0.6 seconds)
                int totalSeconds = (minutes * 60) + seconds;
                this.systemUpdateTicks = (int) Math.ceil(totalSeconds / 0.6);
            }
        }
    }

    @Subscribe
    public void onGameTick(GameTick tick) {
        if (systemUpdateTicks > 0) {
            systemUpdateTicks--;
        }
        if (testTicksRemaining > 0) {
            testTicksRemaining--;
        }
    }

    public int getSystemUpdateTicks() {
        return systemUpdateTicks;
    }

    public void resetTestTicks(int minutes) {
        this.testTicksRemaining = minutes * 100;
    }

    public int getTestTicksRemaining() {
        return testTicksRemaining;
    }

    @Provides
    UpdateTimerConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(UpdateTimerConfig.class);
    }
}
